class Solution {
public:
    int maximumProduct(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<int>> pq(nums.begin(), nums.end());
        while (k > 0) {
            int top = pq.top();
            pq.pop();
            pq.push(top + 1);
            k--;
        }
        long long ans = 1;
        long long MOD = 1e9 + 7;
        while (!pq.empty()) {
            ans = (ans * pq.top()) % MOD;
            pq.pop();
        }
        return ans;
    }
};

class Solution {
    public int maximumProduct(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int x : nums) pq.add(x);
        while (k > 0) {
            pq.add(pq.poll() + 1);
            k--;
        }
        long ans = 1;
        long MOD = 1_000_000_007;
        while (!pq.isEmpty()) {
            ans = (ans * pq.poll()) % MOD;
        }
        return (int) ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
